#[cfg(test)]
mod tests {
    use super::*;

    fn production() -> Settings {
        Settings {
            production: true,
            cookie_secure: true,
            session_hours: 8,
            seed_demo: false,
            mfa_required_for_admins: true,
            demo_secrets: false,
            ..limits()
        }
    }
    fn limits() -> Settings {
        Settings {
            production: false,
            cookie_secure: false,
            session_hours: 8,
            seed_demo: false,
            mfa_required_for_admins: false,
            demo_secrets: false,
            hosted_demo: false,
            demo_password: DemoPassword::Unset,
            rate_limit_login_per_minute: 60,
            rate_limit_requests_per_minute: 600,
            rate_limit_expensive_per_minute: 60,
            access_stale_days: 90,
            access_review_interval_days: 90,
            object_store_url: None,
        }
    }
    fn https() -> ServiceConfig {
        ServiceConfig {
            public_origin: Some("https://loandesk.example".into()),
            ..ServiceConfig::default()
        }
    }

    /// What the platform gives the hosted copy: its own password, seeding on.
    fn hosted() -> Settings {
        Settings {
            hosted_demo: true,
            cookie_secure: true,
            seed_demo: true,
            demo_password: DemoPassword::Supplied,
            ..limits()
        }
    }

    #[test]
    fn a_hosted_demo_keeps_its_demo_logins_and_gives_up_every_other_allowance() {
        assert!(hosted().validate(&https(), false).is_ok());
        assert!(hosted().validate(&ServiceConfig::default(), false).is_err(), "http origin");
        assert!(Settings { cookie_secure: false, ..hosted() }.validate(&https(), false).is_err());
        assert!(Settings { demo_secrets: true, ..hosted() }.validate(&https(), false).is_err());
        assert!(hosted().validate(&https(), true).is_err(), "plaintext database connection");
        let store =
            Settings { object_store_url: Some("http://object-store:9000".into()), ..hosted() };
        assert!(store.validate(&https(), false).is_err(), "plaintext object store");
        // Never together with production, which refuses demo logins outright.
        assert!(Settings { production: true, ..hosted() }.validate(&https(), false).is_err());
        assert!(
            Settings { production: true, seed_demo: false, ..hosted() }
                .validate(&https(), false)
                .is_err()
        );
    }

    #[test]
    fn a_hosted_demo_never_accepts_the_public_demo_password() {
        assert_eq!(DemoPassword::of(Some(PUBLIC_DEMO_PASSWORD)), DemoPassword::PublicDefault);
        assert_eq!(DemoPassword::of(Some("a-password-of-its-own")), DemoPassword::Supplied);
        assert_eq!(DemoPassword::of(Some("")), DemoPassword::Unset);
        assert_eq!(DemoPassword::of(None), DemoPassword::Unset);
        let with = |demo_password| Settings { demo_password, ..hosted() };
        assert!(with(DemoPassword::PublicDefault).validate(&https(), false).is_err());
        assert!(
            with(DemoPassword::Unset).validate(&https(), false).is_err(),
            "nothing to seed with"
        );
        // Refused even when nothing would be seeded with it.
        assert!(
            Settings { seed_demo: false, ..with(DemoPassword::PublicDefault) }
                .validate(&https(), false)
                .is_err()
        );
        assert!(
            Settings { seed_demo: false, ..with(DemoPassword::Unset) }
                .validate(&https(), false)
                .is_ok()
        );
        // The local stack still runs on the documented password.
        let local = Settings { seed_demo: true, ..with(DemoPassword::PublicDefault) };
        assert!(Settings { hosted_demo: false, ..local }.validate(&https(), true).is_ok());
    }

    #[test]
    fn a_hosted_demo_serves_no_api_docs_and_carries_small_files_itself() {
        assert!(!hosted().serves_api_docs());
        assert!(hosted().documents_through_api());
        assert_eq!(hosted().max_upload_bytes(), 4 * 1024 * 1024);
        assert!(!limits().documents_through_api());
        assert_eq!(limits().max_upload_bytes(), 20 * 1024 * 1024);
        assert!(!production().documents_through_api());
    }

    #[test]
    fn production_refuses_every_local_demo_allowance() {
        assert!(production().validate(&https(), false).is_ok());
        assert!(Settings { demo_secrets: true, ..production() }.validate(&https(), false).is_err());
        assert!(Settings { seed_demo: true, ..production() }.validate(&https(), false).is_err());
        assert!(
            Settings { cookie_secure: false, ..production() }.validate(&https(), false).is_err()
        );
        assert!(production().validate(&https(), true).is_err(), "plaintext database connection");
        assert!(production().validate(&ServiceConfig::default(), false).is_err(), "http origin");
    }

    #[test]
    fn calls_to_other_services_use_https_in_production() {
        // The browser origin, the database (verified TLS) and the object store.
        let store = |url: &str| Settings { object_store_url: Some(url.into()), ..production() };
        assert!(store("https://objects.internal.example").validate(&https(), false).is_ok());
        assert!(store("http://object-store:9000").validate(&https(), false).is_err());
        assert!(production().validate(&https(), false).is_ok(), "AWS S3: the SDK's HTTPS endpoint");
        assert!(production().validate(&https(), true).is_err(), "plaintext database connection");
        assert!(production().validate(&ServiceConfig::default(), false).is_err(), "http origin");
        // The local stack talks to its own containers over the Compose network.
        let demo =
            Settings { object_store_url: Some("http://object-store:9000".into()), ..limits() };
        assert!(demo.validate(&ServiceConfig::default(), true).is_ok());
    }

    #[test]
    fn debug_modes_and_development_tools_are_off_in_production() {
        assert!(!production().serves_api_docs(), "no OpenAPI UI in production");
        assert!(limits().serves_api_docs(), "available while developing");
        // Demo data, demo secrets and the plaintext allowances are refused
        // outright: production_refuses_every_local_demo_allowance.
        assert!(Settings { seed_demo: true, ..production() }.validate(&https(), false).is_err());
    }

    #[test]
    fn the_same_allowances_are_fine_for_a_local_demo() {
        let demo = Settings {
            production: false,
            cookie_secure: false,
            seed_demo: true,
            mfa_required_for_admins: false,
            demo_secrets: true,
            session_hours: 8,
            ..limits()
        };
        assert!(demo.validate(&ServiceConfig::default(), true).is_ok());
    }

    #[test]
    fn rate_limits_and_review_periods_cannot_be_switched_off_by_configuration() {
        let ok = limits();
        assert!(ok.validate(&ServiceConfig::default(), true).is_ok());
        for broken in [
            Settings { rate_limit_login_per_minute: 0, ..limits() },
            Settings { rate_limit_requests_per_minute: 0, ..limits() },
            Settings { rate_limit_expensive_per_minute: 0, ..limits() },
            Settings { access_stale_days: 0, ..limits() },
            Settings { access_review_interval_days: 0, ..limits() },
        ] {
            assert!(broken.validate(&ServiceConfig::default(), true).is_err());
        }
    }
}
